import {catalog,catalogMetadata,loadCatalog,loadOccupation,resolveRole,buildReport,MODEL_VERSION} from './engine.js';
import {searchOccupations,hasExactOccupation} from './search.js';
import {prepareOccupation} from './profile.js';
const $=selector=>document.querySelector(selector);
const year=value=>Number.isFinite(value)?String(value):'Not dated';
const safeURL=value=>{try{const url=new URL(value);return ['https:','http:'].includes(url.protocol)?url.href:null;}catch{return null;}};
const prose=value=>Array.isArray(value)?value.join(' '):String(value??'');
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const input=$('#job-input'),form=$('#scan-form'),suggestions=$('#suggestions'),dialog=$('#analysis-dialog');
const scenarioLabels={accelerated:'Faster',central:'Baseline',conservative:'Slower'};
let matches=[],activeSuggestion=-1,state=null,report=null,activeTab='breakthroughs',taskSerial=0,detailsOpen=false,ignoreFocus=false,toastTimer,catalogReady=false,scanRun=0,scanTimer,scanTicker;
const sourceNames={onet:'O*NET · United States',esco:'ESCO · Europe',isco:'ISCO · International group'};
function closeSuggestions(){suggestions.hidden=true;input.setAttribute('aria-expanded','false');input.removeAttribute('aria-activedescendant');activeSuggestion=-1;}
function renderSuggestions(forcedRoles=null){
  if(!catalogReady)return;
  const query=input.value.trim(),exact=!!forcedRoles||hasExactOccupation(query),roles=forcedRoles?forcedRoles.slice(0,50):searchOccupations(query,query&&!exact?5:6);
  matches=roles.map(role=>({role}));if(query&&!exact)matches.push({custom:query});activeSuggestion=-1;
  suggestions.innerHTML=matches.map((match,i)=>`<div id="job-option-${i}" class="suggestion${match.custom?' suggestion-custom':''}" role="option" aria-selected="false" data-suggestion="${i}"><span class="suggestion-copy"><span class="suggestion-title">${match.role?esc(match.role.title):`Explore “${esc(match.custom)}”`}</span><span class="suggestion-subtitle">${match.role?esc(sourceNames[match.role.source]||match.role.sector):'Describe your work'}</span></span><span class="suggestion-arrow" aria-hidden="true">↗</span></div>`).join('');
  suggestions.hidden=!matches.length;
  const rect=form.getBoundingClientRect(),viewport=window.visualViewport,bottom=viewport?viewport.height+viewport.offsetTop:window.innerHeight;
  const below=bottom-rect.bottom-18,above=rect.top-(viewport?.offsetTop||0)-18,desiredHeight=Math.min(340,matches.length*61+14),opensUp=below<Math.min(260,desiredHeight)&&above>below;
  suggestions.classList.toggle('opens-up',opensUp);suggestions.style.maxHeight=`${Math.max(110,Math.min(340,opensUp?above:below))}px`;
  input.setAttribute('aria-expanded',String(!!matches.length));input.removeAttribute('aria-activedescendant');
  $('#search-status').textContent=query?`${roles.length} matching occupations${!exact?'. Or describe your own work.':'.'}`:`Search ${catalog.length.toLocaleString()} source records. Use arrow keys to choose.`;
}
function highlightSuggestion(index){if(!matches.length)return;activeSuggestion=(index+matches.length)%matches.length;suggestions.querySelectorAll('[data-suggestion]').forEach((el,i)=>{const selected=i===activeSuggestion;el.classList.toggle('is-active',selected);el.setAttribute('aria-selected',String(selected));if(selected)el.scrollIntoView({block:'nearest'});});input.setAttribute('aria-activedescendant',`job-option-${activeSuggestion}`);}
function chooseSuggestion(index){const selected=matches[index];if(!selected)return;input.value=selected.role?.title||selected.custom;closeSuggestions();begin(input.value,selected.role,!!selected.custom);}
function stopScan(){scanRun++;clearTimeout(scanTimer);clearInterval(scanTicker);dialog.classList.remove('is-scanning');}
function openDialog(){if(!dialog.open)dialog.showModal();dialog.scrollTop=0;}
function begin(query,chosenRole,forceCustom=false){
  if(!catalogReady)return;stopScan();input.setCustomValidity('');closeSuggestions();
  const resolved=resolveRole(query);
  if(!forceCustom&&!chosenRole&&resolved.ambiguous){input.focus();renderSuggestions(resolved.candidates);$('#search-status').textContent='Several occupations use that title. Choose the one that matches your work.';return;}
  const role=forceCustom?null:chosenRole||(resolved.confidence==='Title match'?resolved.role:null);
  state={title:role?.title||query.trim(),tasks:[],scenario:'central',matched:!!role,occupation:null};activeTab='breakthroughs';detailsOpen=false;
  if(!role){renderEditor();openDialog();$('#dialog-title').focus({preventScroll:true});return;}
  runAnalysis(async()=>{
    const occupation=await loadOccupation(role.id);
    const tasks=prepareOccupation(occupation).tasks;
    return {...state,title:occupation.title,occupation,tasks:structuredClone(tasks)};
  });
}
function updateReport(){report=buildReport(state);}
function renderScan(){
  dialog.classList.add('is-scanning');
  $('#dialog-content').innerHTML=`<div class="scan-stage"><p class="scan-eyebrow">AFTERMATH / FORECAST ENGINE</p><h2 id="dialog-title" class="scan-job" tabindex="-1">${esc(state.title)}</h2><div class="scan-aperture" aria-hidden="true"><div class="aperture-ring ring-outer"></div><div class="aperture-ring ring-middle"></div><div class="aperture-ring ring-inner"></div><span class="scan-crosshair"></span><div class="scan-core"><span class="scan-core-label">PROJECTING</span><span id="scan-digits">····</span></div><span class="scan-sweep"></span></div><p id="scan-status" class="scan-status" role="status">Loading the task profile</p><div class="scan-progress" aria-hidden="true"><span id="scan-progress-bar"></span></div><p id="scan-detail" class="scan-detail">Published occupation data. Versioned research.</p><button type="button" id="skip-reveal" class="scan-skip" disabled>Show result</button></div>`;
  openDialog();$('#dialog-title').focus({preventScroll:true});
}
async function runAnalysis(prepare){
  stopScan();const ticket=scanRun;renderScan();
  const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
  let prepared;
  try{prepared=await prepare();if(ticket!==scanRun||!dialog.open)return;state=prepared;updateReport();}
  catch(error){if(ticket!==scanRun)return;dialog.classList.remove('is-scanning');$('#dialog-content').innerHTML=`<p class="report-kicker">Could not finish</p><h2 id="dialog-title" class="dialog-title">Data unavailable</h2><p class="dialog-description">${esc(error.message)} Please close this window and try again.</p>`;return;}
  const finish=()=>{if(ticket!==scanRun||!dialog.open)return;clearTimeout(scanTimer);clearInterval(scanTicker);dialog.classList.remove('is-scanning');renderReport();dialog.scrollTop=0;$('#dialog-title').focus({preventScroll:true});$('.report-summary').classList.add('year-reveal');};
  if(reduced){finish();return;}
  $('#skip-reveal').disabled=false;$('#skip-reveal').addEventListener('click',finish,{once:true});
  const stages=[
    ['Reading the work',`${report.tasks.length} task or skill requirements loaded`,19],
    ['Mapping the breakthroughs',`${report.capabilities.length} required technology areas identified`,47],
    ['Tracing the slowest dependency',`${report.sources.length} research references linked to the model`,76],
    ['Resolving your baseline','A conditional scenario. Not a guaranteed date.',96]
  ];
  let stage=0;
  const advance=()=>{if(ticket!==scanRun||!dialog.open)return;const [label,detail,progress]=stages[stage];$('#scan-status').textContent=label;$('#scan-detail').textContent=detail;$('#scan-progress-bar').style.width=`${progress}%`;stage++;if(stage<stages.length)scanTimer=setTimeout(advance,950);else scanTimer=setTimeout(finish,950);};
  let frame=0;scanTicker=setInterval(()=>{if(ticket!==scanRun||!$('#scan-digits'))return;frame++;$('#scan-digits').textContent=String(2026+((frame*37)%173));},145);advance();
}
function editorRows(){return state.tasks.map((task,i)=>`<div class="task-edit-row"><span aria-hidden="true">${String(i+1).padStart(2,'0')}</span><input aria-label="Task ${i+1}" data-task-index="${i}" value="${esc(task.label)}" maxlength="2000"><button type="button" data-remove="${i}" aria-label="Remove task ${i+1}">×</button></div>`).join('');}
function renderEditor(){
  $('#dialog-content').innerHTML=`<p class="report-kicker">${state.matched?'Make it your job':'Describe the work'}</p><h2 id="dialog-title" class="dialog-title" tabindex="-1">${esc(state.title)}</h2><p class="dialog-description">${state.matched?'Keep the requirements that apply. Add anything missing.':'Describe the tasks, tools, setting, and difficult exceptions. The model maps those requirements to technology areas.'}</p><div class="task-edit-list">${editorRows()}</div><form id="add-task-form" class="add-task-form"><input id="new-task" aria-label="New task" placeholder="What does this job involve?" maxlength="2000" required><button type="submit" aria-label="Add task">Add +</button></form><p id="editor-error" class="editor-error" role="status"></p><div class="dialog-actions"><span>Edited requirements use provisional mapping.</span><button type="button" id="generate-report" class="primary-button">Find my year <span aria-hidden="true">↗</span></button></div>`;
  $('#add-task-form').addEventListener('submit',event=>{event.preventDefault();const label=$('#new-task').value.trim();if(!label)return;if(state.tasks.length>=500){$('#editor-error').textContent='This profile is at its 500-requirement limit.';return;}if(state.tasks.some(t=>t.label.trim().toLocaleLowerCase()===label.toLocaleLowerCase())){$('#editor-error').textContent='That requirement is already listed.';return;}state.tasks.push({id:`added-${++taskSerial}`,label,type:'custom-task'});renderEditor();$('#new-task').focus();});
  $('#generate-report').addEventListener('click',()=>{state.tasks=state.tasks.filter(task=>task.label.trim());if(!state.tasks.length){$('#editor-error').textContent='Add at least one task to continue.';$('#new-task').focus();return;}runAnalysis(async()=>({...state,tasks:structuredClone(state.tasks)}));});
}
function evidenceText(source){return source.observation||source.finding||source.summary||source.claim||'';}
function renderEvidence(source){return `<a class="report-source" href="${esc(source.url)}" target="_blank" rel="noopener noreferrer"><span>${esc(source.title)} ↗</span><small>${esc(source.publisher||source.authors||'Primary research')} · ${source.dateType?.startsWith('reviewed')?'Reviewed ':''}${esc(source.date||source.year||'')}</small>${evidenceText(source)?`<p>${esc(evidenceText(source))}</p>`:''}${source.limitation?`<p class="source-limit">Limit: ${esc(source.limitation)}</p>`:''}</a>`;}
function renderReport(){
  const r=report;
  const sourceNote=r.profileCustomized?'Your adapted task profile.':r.sourceCoverage==='skills'?'Essential skills used as work proxies.':r.source==='isco'?'A broad occupational group; choose more specific work below.':r.source==='custom'?'Based on your description.':'';
  const coverageNote=r.forecastStatus==='insufficient-evidence'?(r.workflow.status==='outside-source-grid'?'The source distributions do not support a year within the modeled horizon for this scenario. No date is substituted.':'The available requirements do not support a date. Add details or choose a specific occupation.'):r.forecastStatus==='partial'?`A partial projection: ${r.coverage.undatedTasks} ${r.coverage.undatedTasks===1?'requirement has an evidence gap':'requirements have evidence gaps'} that could delay this year.`:'A source-based scenario, not a guaranteed year. Full-workflow integration and reliable operation remain conditions.';
  const driver=r.capabilities.find(cap=>Number.isFinite(cap.baselineYear)&&cap.baselineYear===r.bottleneckYear);
  const related=(state.occupation?.relatedEscoIds||[]).map(id=>catalog.find(role=>role.id===id)).filter(Boolean);
  $('#dialog-content').innerHTML=`<p class="report-kicker">Your automation outlook</p><div class="report-title-row"><div><h2 id="dialog-title" class="dialog-title" tabindex="-1">${esc(r.title)}</h2><p class="report-meta">${r.tasks.length} requirement${r.tasks.length===1?'':'s'} · ${r.capabilities.filter(cap=>cap.id!=='unknown').length} technology areas${r.sourceCode?` · ${esc(r.sourceCode)}`:''}</p></div><button type="button" class="quiet-button" id="edit-tasks">Edit tasks ↗</button></div>
  <section class="report-summary" aria-label="Conditional full automation estimate"><p class="report-kicker">${scenarioLabels[state.scenario]} ${r.forecastStatus==='partial'?'partial scenario':'scenario'} · full automation</p><div class="report-years ${r.baselineYear===null?'is-undated':''}">${esc(year(r.baselineYear))}</div><p class="report-disclaimer">${esc(coverageNote)} ${esc(sourceNote)}</p>${driver?`<p class="year-driver">Latest individual milestone: <strong>${esc(driver.label)}</strong></p>`:''}</section>
  ${related.length?`<details class="related-roles"><summary>Choose specific work in this group (${related.length})</summary><div>${related.map(role=>`<button type="button" class="quiet-button" data-role="${esc(role.id)}">${esc(role.title)} ↗</button>`).join('')}</div></details>`:''}
  <div class="scenario-switch" role="group" aria-label="Pace of development">${['accelerated','central','conservative'].map(key=>`<button type="button" class="scenario-pill${key===state.scenario?' selected':''}" data-scenario="${key}" aria-pressed="${key===state.scenario}">${scenarioLabels[key]}</button>`).join('')}</div>
  <div class="report-tabs" role="tablist" aria-label="Explore your result">${[['breakthroughs','Why this year'],['tasks','The work'],['research','The research']].map(([key,label])=>`<button type="button" role="tab" id="tab-${key}" aria-controls="report-panel" aria-selected="${activeTab===key}" tabindex="${activeTab===key?0:-1}" data-tab="${key}">${label}</button>`).join('')}</div><section id="report-panel" class="tab-panel" role="tabpanel" aria-labelledby="tab-${activeTab}" tabindex="0"></section>
  <details class="report-details" ${detailsOpen?'open':''}><summary>Method & limits</summary><div class="report-detail-copy"><p>Every requirement is considered. Published milestone forecasts and task-level evidence replace fixed generic delays. The projection combines distinct milestone distributions because every required breakthrough must arrive. Repeated references to the same breakthrough count once. Undated requirements remain visible and may push it later.</p><p>Numerical software benchmarks are measured at specific success rates. Expert milestone forecasts are opinions. Transferring either to an entire job requires assumptions; these are not validated whole-job deadlines. No random offsets are added to make jobs look different.</p><ul>${r.assumptions.map(item=>`<li>${esc(item)}</li>`).join('')}</ul><p>${r.workflow.eventCount} distinct milestone events · shared-progress weight ${r.workflow.sharedWeight}. This dependence assumption is not fitted to observations. Changing this assumption can materially change the year. Sensitivity calculations are included in the saved report; they are not confidence bounds.</p><h3>Known limits</h3><ul>${r.limitations.map(item=>`<li>${esc(item)}</li>`).join('')}</ul>${r.suppressedConstraints?.length?`<h3>Human abilities that do not imply robots</h3><ul>${r.suppressedConstraints.map(item=>`<li>${esc(item.reason)}</li>`).join('')}</ul>`:''}<p>Model ${esc(MODEL_VERSION)} · research reviewed October 31, 2026. This is a versioned research snapshot, not a live literature search.</p></div></details><div class="report-foot"><span>Your search stays in this browser.</span><button type="button" id="download-report" class="quiet-button">Save report ↓</button></div>`;
  renderPanel();$('#edit-tasks').addEventListener('click',()=>{renderEditor();dialog.scrollTop=0;$('#dialog-title').focus({preventScroll:true});});$('#download-report').addEventListener('click',downloadReport);$('.report-details').addEventListener('toggle',event=>detailsOpen=event.target.open);
}
const tierLabel=value=>({E0:'No qualifying demonstration',E1:'Robot-adapted environment',E2:'Predictable human facility',E3:'Unstructured environment'}[value]||value||'Not assessed');
function taskResearchHTML(task){
  const evidence=task.sourceId?task.automationEvidence:null;if(!evidence)return '';
  const links=(evidence.sources||[]).filter(source=>safeURL(source.url));
  return `<details class="task-research"><summary>Published task research${links.length?` · ${links.length} references`:''}</summary><p>The external study classified this task as ${evidence.physical?'physical':'nonphysical'}${evidence.exposureTier?` (${esc(tierLabel(evidence.exposureTier))})`:''}. These are AI-assisted research assessments, not independently verified full-workflow trials.</p>${evidence.instances?.length?`<ul>${evidence.instances.map(item=>`<li>${esc(item.label)} <small>Evidence: ${esc(tierLabel(item.tier))} · Required setting: ${esc(tierLabel(item.settingTier))}</small></li>`).join('')}</ul>`:''}${links.map(source=>`<a class="report-source" href="${esc(safeURL(source.url))}" target="_blank" rel="noopener noreferrer"><span>${esc(source.system||source.title)} ↗</span><small>${esc(source.maturity)} · ${esc(source.autonomyStatus)} · ${esc(source.date)}</small><p>${esc(source.claim)}</p>${source.transferJustification?`<p class="source-limit">Transfer assumption: ${esc(source.transferJustification)}</p>`:''}</a>`).join('')}</details>`;
}
function renderPanel(){
  const r=report;
  if(activeTab==='breakthroughs'){
    const max=Math.max(...r.capabilities.map(cap=>Number.isFinite(cap.baselineYear)?cap.baselineYear-r.assessmentYear:0),1);
    $('#report-panel').innerHTML=`<p class="panel-intro">The work determines the technology. The projection combines ${r.workflow.eventCount} distinct milestone events. The markers below show individual requirements; gaps stay visible.</p>${r.capabilities.map(cap=>`<article class="breakthrough"><div class="breakthrough-heading"><h3>${esc(cap.label)}${Number.isFinite(cap.baselineYear)&&cap.baselineYear===r.bottleneckYear?'<span class="breakthrough-note">Latest marker</span>':''}</h3><span class="breakthrough-range">${year(cap.baselineYear)}</span></div><p>${esc(cap.basis||prose(cap.requirements))}</p>${Number.isFinite(cap.baselineYear)?`<div class="breakthrough-track" aria-hidden="true"><span style="width:${Math.max(4,(cap.baselineYear-r.assessmentYear)/max*100)}%"></span></div>`:''}<details class="capability-details"><summary>Driving tasks & evidence</summary><p>${esc(prose(cap.requirements))}</p>${(cap.taskIds||[]).length?`<ul class="driving-tasks">${cap.taskIds.map(id=>r.tasks.find(task=>task.id===id)).filter(Boolean).map(task=>`<li>${esc(task.label)}</li>`).join('')}</ul>`:''}${(cap.anchors||[]).map(anchor=>`<div class="milestone-anchor"><strong>${esc(anchor.label)} · ${year(anchor.baselineYear)}</strong><p>${esc(anchor.observableOutcome)}</p><p>${esc(anchor.reason)} ${esc(anchor.matchType)}</p><small>Published expert forecast · ${esc(anchor.milestoneId)}${anchor.subsumedByOccupation?' · Covered by the full-occupation forecast; not added separately':''}</small></div>`).join('')}${(cap.assumptions||[]).map(text=>`<p>${esc(text)}</p>`).join('')}${(cap.evidenceIds||[]).map(id=>r.sources.find(source=>source.id===id)).filter(Boolean).map(source=>`<a href="${esc(source.url)}" target="_blank" rel="noopener noreferrer">${esc(source.title)} ↗</a>`).join('')}</details></article>`).join('')}<p class="integration-note">Integration, reliability, cost and permission remain conditions of the full-automation scenario. No arbitrary extra-year allowance is added.</p>`;
  }else if(activeTab==='tasks'){
    const taskHTML=task=>`<article class="report-task"><header><h3>${esc(task.label)}</h3><span>${year(task.baselineYear)}</span></header><p>${esc(prose(task.requirements))}</p><small>${esc(task.mappingBasis)}${task.physicalScopeGap?' · Physical scope needs review':task.undatedCapabilityIds?.length?' · Evidence gap':''}</small>${task.horizonBasis?`<p class="source-limit">${esc(task.horizonBasis)}</p>`:''}${taskResearchHTML(task)}</article>`;
    $('#report-panel').innerHTML=`<p class="panel-intro">All ${r.tasks.length} requirements are considered.${r.sourceCoverage==='skills'&&!r.profileCustomized?' These are essential skill proxies from ESCO.':r.profileCustomized?' This profile includes your adaptations.':''}</p>${r.tasks.slice(0,12).map(taskHTML).join('')}${r.tasks.length>12?`<details class="more-tasks"><summary>Show all ${r.tasks.length} requirements</summary>${r.tasks.slice(12).map(taskHTML).join('')}</details>`:''}`;
  }else{
    $('#report-panel').innerHTML=`<p class="panel-intro">Measured performance, expert forecasts, and transfer assumptions are different evidence.${r.coverage.researchedTasks?` ${r.coverage.researchedTasks} duties have linked task assessments and ${r.coverage.linkedTaskCitations.toLocaleString()} references, available under The work.`:''}</p>${r.benchmarkComponents.length?`<div class="benchmark-note"><h3>Measured software progress</h3><p>A separate benchmark analysis reproduces METR's published software measurements. It provides context and does not determine the job's displayed year. Its measured 50% and 80% success thresholds do not prove reliable full-job autonomy. The repository documents later-observation testing and substantial prediction errors.</p><a href="https://github.com/sigenyi/aftermath/blob/main/research/DIGITAL-CALIBRATION.md" target="_blank" rel="noopener noreferrer">View measurements & validation ↗</a></div>`:''}${r.sourceRecord?`<h3 class="research-label">Occupation reference</h3>${renderEvidence(r.sourceRecord)}`:''}<h3 class="research-label">Relevant research</h3>${r.sources.map(renderEvidence).join('')}<p class="integration-note">The corpus is not exhaustive. Task research contains externally generated assessments whose cited claims have not all been independently reviewed here.</p>`;
  }
}
function downloadReport(){
  const r=report,lines=[`AFTERMATH — ${r.title}`,`Conditional full-automation scenario: ${year(r.baselineYear)}`,`Evidence status: ${r.forecastStatus}`,`Scenario: ${scenarioLabels[r.scenario]}`,`Source: ${r.source} ${r.sourceCode||''}`,`Generated: ${r.generatedAt}`,`Model: ${MODEL_VERSION}`,`Distinct milestone events: ${r.workflow.eventCount}`,`Joint timing: ${r.workflow.formula}; shared-progress weight ${r.workflow.sharedWeight} (unfitted scenario assumption)`,`Dependence sensitivity: shared ${year(r.workflow.sensitivity?.perfectlySharedYear)}; independent ${year(r.workflow.sensitivity?.independentYear)} (not confidence bounds)`,
    'DATA CREDITS: O*NET 31.0 Database, U.S. Department of Labor/Employment and Training Administration. CC BY 4.0: https://creativecommons.org/licenses/by/4.0/ . AFTERMATH modified/restructured the data; USDOL/ETA has not approved, endorsed, or tested the modifications. O*NET is a trademark of USDOL/ETA. This service uses the ESCO classification of the European Commission. ISCO codes/titles: International Labour Organization. Task-level robot research: Legate-Yang and Massenkoff / Anthropic, CC BY 4.0, based on O*NET 29.3. Published AI-assisted assessments, not independent trials.',
    'A conditional point projection, not a calibrated whole-job probability or personal layoff date.','', 'TECHNOLOGY REQUIREMENTS'];
  for(const cap of r.capabilities){lines.push(`${cap.label}: ${year(cap.baselineYear)}`,`Basis: ${cap.basis||''}`,prose(cap.requirements),`Evidence: ${(cap.evidenceIds||[]).join(', ')}`,...(cap.anchors||[]).map(anchor=>`${anchor.label}: ${year(anchor.baselineYear)} — ${anchor.observableOutcome}. ${anchor.reason} [${anchor.milestoneId}]`),`Assumptions: ${(cap.assumptions||[]).join('; ')}`,'');}
  lines.push('WORK PROFILE');
  for(const task of r.tasks){lines.push(task.label,`Mapped milestone: ${year(task.baselineYear)}`,prose(task.requirements),`Mapping: ${task.mappingBasis}`,`Numeric basis: ${task.horizonBasis||'Insufficient evidence'}`);
    const evidence=task.sourceId?task.automationEvidence:null;
    if(evidence){lines.push(`Published task assessment: physical=${evidence.physical}; tier=${evidence.exposureTier||'not applicable'}`,...(evidence.instances||[]).map(item=>`Example: ${item.label} (${item.tier}; setting ${item.settingTier})`),...(evidence.sources||[]).map(source=>`${source.system||source.title} — ${source.date} — ${source.maturity} / ${source.autonomyStatus}\n${source.url}\n${source.claim}${source.transferJustification?`\nTransfer: ${source.transferJustification}`:''}`));}lines.push('');}
  lines.push('ASSUMPTIONS',...r.assumptions,'','LIMITS',...r.limitations,'','SOURCES',...[r.sourceRecord,...r.sources].filter(Boolean).map(source=>`${source.title}\n${source.url}\n${evidenceText(source)}\n${source.limitation||''}`));
  const url=URL.createObjectURL(new Blob([lines.join('\n')],{type:'text/plain;charset=utf-8'})),link=document.createElement('a');link.href=url;link.download=`aftermath-${r.title.toLowerCase().replace(/[^\p{L}\p{N}]+/gu,'-').slice(0,60)||'report'}.txt`;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);clearTimeout(toastTimer);$('#toast').textContent='Report saved.';$('#toast').hidden=false;toastTimer=setTimeout(()=>$('#toast').hidden=true,3000);
}
input.addEventListener('focus',()=>{if(ignoreFocus){ignoreFocus=false;return;}renderSuggestions();});
input.addEventListener('input',()=>{input.setCustomValidity('');renderSuggestions();});
input.addEventListener('keydown',event=>{if(event.key==='ArrowDown'||event.key==='ArrowUp'){event.preventDefault();if(suggestions.hidden)renderSuggestions();highlightSuggestion(event.key==='ArrowDown'?activeSuggestion+1:activeSuggestion<0?matches.length-1:activeSuggestion-1);}else if(event.key==='Escape'){event.preventDefault();closeSuggestions();}else if(event.key==='Enter'&&!suggestions.hidden&&activeSuggestion>=0){event.preventDefault();chooseSuggestion(activeSuggestion);}else if(event.key==='Tab')closeSuggestions();});
form.addEventListener('submit',event=>{event.preventDefault();const query=input.value.trim();if(!query){input.setCustomValidity('Enter your job title.');input.reportValidity();return;}if(!suggestions.hidden&&activeSuggestion>=0)chooseSuggestion(activeSuggestion);else begin(query);});
suggestions.addEventListener('pointerdown',event=>{if(event.target.closest('[data-suggestion]'))event.preventDefault();});
suggestions.addEventListener('click',event=>{const item=event.target.closest('[data-suggestion]');if(item)chooseSuggestion(Number(item.dataset.suggestion));});
document.addEventListener('pointerdown',event=>{if(!form.contains(event.target))closeSuggestions();});
$('#close-dialog').addEventListener('click',()=>{stopScan();dialog.close();});dialog.addEventListener('cancel',stopScan);dialog.addEventListener('close',()=>{stopScan();ignoreFocus=true;input.focus({preventScroll:true});closeSuggestions();});
$('#about-button').addEventListener('click',()=>$('#about-dialog').showModal());$('#close-about').addEventListener('click',()=>$('#about-dialog').close());
document.addEventListener('click',event=>{
  const example=event.target.closest('[data-role]');if(example){const role=catalog.find(item=>item.id===example.dataset.role);if(role){input.value=role.title;begin(role.title,role);}return;}
  const remove=event.target.closest('[data-remove]');if(remove){const i=Number(remove.dataset.remove);state.tasks.splice(i,1);renderEditor();(document.querySelector(`[data-task-index="${Math.min(i,state.tasks.length-1)}"]`)||$('#new-task')).focus();return;}
  const tab=event.target.closest('[data-tab]');if(tab){activeTab=tab.dataset.tab;document.querySelectorAll('[data-tab]').forEach(button=>{button.setAttribute('aria-selected',String(button===tab));button.tabIndex=button===tab?0:-1;});$('#report-panel').setAttribute('aria-labelledby',tab.id);renderPanel();return;}
  const scenario=event.target.closest('[data-scenario]');if(scenario){state.scenario=scenario.dataset.scenario;const position=dialog.scrollTop;updateReport();renderReport();dialog.scrollTop=position;document.querySelector(`[data-scenario="${state.scenario}"]`).focus({preventScroll:true});}
});
document.addEventListener('input',event=>{if(event.target.matches('[data-task-index]')){const task=state.tasks[Number(event.target.dataset.taskIndex)];task.label=event.target.value;task.type='edited-task';delete task.sourceId;delete task.automationEvidence;}});
document.addEventListener('keydown',event=>{if(!event.target.matches('[role="tab"]')||!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;event.preventDefault();const tabs=[...document.querySelectorAll('[role="tab"]')],index=tabs.indexOf(event.target),next=event.key==='Home'?0:event.key==='End'?tabs.length-1:(index+(event.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;tabs[next].click();tabs[next].focus();});
async function initialize(){
  $('#search-button').disabled=true;input.disabled=true;input.placeholder='Loading occupation catalog…';
  try{await loadCatalog();catalogReady=true;input.disabled=false;$('#search-button').disabled=false;input.placeholder='What do you do?';$('#catalog-status').textContent=`${catalog.length.toLocaleString()} occupation records · O*NET / ESCO / ISCO`;$('#catalog-status').title='Source records overlap; this is not a count of unique worldwide jobs.';$('#coverage-details').textContent=Object.entries(catalogMetadata.sources||{}).map(([key,value])=>`${key.toUpperCase()}: ${value.count.toLocaleString()} records (${value.version})`).join(' · ');if(document.activeElement===input)renderSuggestions();}
  catch(error){input.placeholder='Catalog unavailable';$('#catalog-status').innerHTML='<button type="button" id="retry-catalog">Could not load occupations. Retry ↻</button>';$('#retry-catalog').addEventListener('click',initialize,{once:true});}
}
closeSuggestions();initialize();
